import styled from '@emotion/styled';
import * as TabsPrimitive from '@radix-ui/react-tabs';
import { theme } from 'theme';

export const TabsListContainer = styled('div')({
  display: 'flex',
  flexDirection: 'column',
  overflow: 'auto',
  width: '100%',
});

export const TabsListBox = styled('div')({
  alignItems: 'center',
  display: 'flex',
  flexDirection: 'row',
});

export const TabsArrowButton = styled('button')({
  all: 'unset',
  alignItems: 'center',
  cursor: 'pointer',
  display: 'none',
  height: '24px',
  justifyContent: 'center',
  padding: '0 5px',
  '@media (min-width: 56.25rem)': {
    display: 'flex',
  },
});

export const StyledTabsRoot = styled(TabsPrimitive.Root)({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
});

export const StyledTabsList = styled(TabsPrimitive.List)({
  display: 'flex',
  overflow: 'auto',
  width: '100%',
  '&::-webkit-scrollbar': {
    display: 'none',
  },
});

export const StyledTabsTrigger = styled(TabsPrimitive.Trigger)({
  all: 'unset',
  alignItems: 'center',
  backgroundColor: 'transparent',
  boxSizing: 'border-box',
  color: theme.colors.interfaceLabelPrimary,
  cursor: 'pointer',
  display: 'flex',
  fontFamily: theme.fonts.heading,
  fontSize: theme.fonts.fontSizes['3'],
  fontWeight: theme.fonts.fontWeights.semibold,
  height: '36px',
  justifyContent: 'center',
  lineHeight: 1,
  padding: `0 ${theme.spacing['6']}`,
  whiteSpace: 'nowrap',
  width: '100%',
  '&:hover': {
    backgroundColor: theme.colors.interfaceSurfacePrimary,
  },
  '&[data-state="active"]': {
    backgroundColor: 'transparent',
    boxShadow: 'inset 0 -1px 0 0 currentColor, 0 1px 0 0 currentColor',
    color: theme.colors.interfaceLabelPrimary,
  },
  '&[data-state="active"]:hover': {
    backgroundColor: theme.colors.interfaceSurfacePrimary,
  },
  '&:disabled': {
    backgroundColor: 'transparent',
    color: theme.colors.interfaceLabelDisabled,
    cursor: 'default',
  },
  '@media (min-width: 56.25rem)': {
    height: '52px',
    width: 'auto',
  },
});

export const StyledTabsListDivider = styled('div')({
  marginBottom: theme.spacing['6'],
  width: '100%',
});

export const StyledTabsContent = styled(TabsPrimitive.Content)({
  backgroundColor: theme.colors.neutral0,
  borderBottomLeftRadius: '6px',
  borderBottomRightRadius: '6px',
  flexGrow: 1,
  outline: 'none',
  padding: '20px',
});
